KG42.register("rules-ac1c775293a454bec63525e4",{"id":"22-decentralized_flexibility_markets::v141-c-R005","paper":"22-decentralized_flexibility_markets","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Prosumer participation","process_stage":"participation","market_meaning":"Prosumer participation is opt-in; prosumers individually decide whether to participate and the conditions under which they are willing to provide flexibility. Scope: Prosumer participation in the proposed distribution-network flexibility market. Prosumers owning local flexible generation sources may directly sell flexibility contracts. Scope: Direct flexibility selling by prosumers in the proposed market. Condition: The prosumer owns local flexible generation sources. Before entry, each prosumer first plans a demand profile for its flexible energy resources using its local energy management system and considering retail-market costs and preferences. Scope: Preparation for prosumer entry into the proposed flexibility market. Condition: Prior to entering the flexibility market.","independence_rationale":"Relations governed by the approved function participation.prosumer under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["participation.prosumer"],"E":[],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Direct flexibility selling by prosumers in the proposed market. | Preparation for prosumer entry into the proposed flexibility market. | Prosumer participation in the proposed distribution-network flexibility market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E07","v141-b-g01-E17","v141-b-g02-e34"]},"x":[],"theta":[],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Prosumer participation is opt-in; prosumers individually decide whether to participate and the conditions under which they are willing to provide flexibility. Scope: Prosumer participation in the proposed distribution-network flexibility market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E02","v141-b-g02-e34"]},{"constraint_id":"v141-c-R005-C002","kind":"procedural","role":"core","statement":"Prosumers owning local flexible generation sources may directly sell flexibility contracts. Scope: Direct flexibility selling by prosumers in the proposed market. Condition: The prosumer owns local flexible generation sources.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E17"]},{"constraint_id":"v141-c-R005-C003","kind":"procedural","role":"core","statement":"Before entry, each prosumer first plans a demand profile for its flexible energy resources using its local energy management system and considering retail-market costs and preferences. Scope: Preparation for prosumer entry into the proposed flexibility market. Condition: Prior to entering the flexibility market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E07"]}],"pi":[{"evidence_id":"v141-b-g01-E02","location":{"location_id":"src-12c011a9b5-p02-c2r4__v141-a-M01-participation","page":2,"printed_page":null,"section":"I. Introduction; design requirements","anchor_text":"g g q ve r The ﬂexibility market should be opt-in for prosumers, and should account for their incent","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"condition"},"source_text":"The flexibility market should be opt-in for prosumers, and should account for their incentives within the retail electricity market."},{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-12c011a9b5-p03-c1r4__v141-a-M01-participation","page":3,"printed_page":null,"section":"II. Decentralized Flexibility Market Design","anchor_text":"p gg g q g the paper, the DSO, prosumers and aggregators participating in m the market are generical","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"unknown"},"source_text":"The DSO organizes a flexibility market if it predicts the distribution network demand limits could be violated. Prior to entering the flexibility market, each prosumer first plans a demand profile for their flexible energy resources, considering their costs and preferences in the retail market, using their local energy management systems."},{"evidence_id":"v141-b-g01-E17","location":{"location_id":"src-12c011a9b5-p04-c1r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III.A Prosumer Preferences","anchor_text":"p , energy resources. The prosumers sell contracts for time intervals Ui when they are willing to re","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Let \\(\\mathcal{P} \\subseteq A\\) be the set of prosumers in the trading network. The prosumers have renewable sources, inflexible loads and flexible energy resources. The prosumers sell contracts for time intervals when they are willing to reduce their planned retail market demand. If prosumers own local flexible generation sources, they can directly sell flexibility contracts. Prosumers with energy storage systems may only be willing to sell contracts if they are able to buy contracts for other time intervals allowing them to increase their retail demand."},{"evidence_id":"v141-b-g02-e34","location":{"location_id":"src-12c011a9b5-p09-c2r1__v141-a-M01-participation","page":9,"printed_page":null,"section":"VII. Conclusion","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 3, MAY 2019 VII. CONCLUSION A decentralized market ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"condition"},"source_text":"A key advantage of the proposed market design is that it can be implemented alongside existing retail electricity market arrangements. The market design could help integrate flexibility from prosumers with preferences for autonomy and privacy, since it requires only individual decision making and aggregator-to-prosumer negotiation. Prosumers can individually decide whether to participate or not, and the conditions under which they are willing to provide flexibility."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":"The source states opt-in participation, an ownership condition for direct selling, and pre-entry demand-profile planning as prose process requirements; it defines no decision variable for this participation rule in the supplied evidence.","empty_theta_reason":"No numerical or symbolic fixed parameter is specified for this participation rule in the supplied evidence; the ownership condition is text, not a parameter."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"participation.prosumer","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E02","quote":"The flexibility market should be opt-in for prosumers, and should account for their incentives within the retail electricity market."},{"evidence_id":"v141-b-g02-e34","quote":"Prosumers can individually decide whether to participate or not, and the conditions under which they are willing to provide flexibility."}],[{"evidence_id":"v141-b-g01-E17","quote":"If prosumers own local flexible generation sources, they can directly sell flexibility contracts."}],[{"evidence_id":"v141-b-g01-E07","quote":"Prior to entering the flexibility market, each prosumer first plans a demand profile for their flexible energy resources, considering their costs and preferences in the retail market, using their local energy management systems."}]],"C2_formalization":{"graph_sha256":"1cb60b63782f0e6433d76ee18bbaa63554ff7b045cde57d57d53b051ebeabdec","applicability":"non_mathematical","reason":"This is a procedural/admission rule: the supplied evidence states opt-in participation, an ownership condition for direct flexibility selling, and a pre-entry planning step, with no mathematical expression or optimization variable for the participation function. B evidence remains unreviewed.","bindings":[],"revision_requests":[]}},"quarantined_references":[]}});
